class Solution {
public:
    vector<vector<int>> mergeSimilarItems(vector<vector<int>>& items1, vector<vector<int>>& items2) {
        int cnt[1001] = {0};
        for (const auto& it : items1) {
            cnt[it[0]] += it[1];
        }
        for (const auto& it : items2) {
            cnt[it[0]] += it[1];
        }
        vector<vector<int>> ret;
        for (int v = 1; v <= 1000; ++v) {
            if (cnt[v] > 0) {
                ret.push_back({v, cnt[v]});
            }
        }
        return ret;
    }
};
